async function screenshotB64(page: import('@playwright/test').Page, selector: string) {
  await page.evaluate(() => window.scrollTo(0, 0))
  await page.waitForTimeout(200)
  const loc = page.locator(selector).first()
  await loc.waitFor({ state: 'visible', timeout: 30_000 })
  const box = await loc.boundingBox()
  if (!box) throw new Error(`no box for ${selector}`)
  const clip = {
    x: 0,
    y: Math.max(0, Math.min(box.y, 844 - 1)),
    width: 390,
    height: Math.min(844, Math.max(1, box.height)),
  }
  if (clip.y + clip.height > 844) clip.height = 844 - clip.y
  const buf = await page.screenshot({ animations: 'disabled', clip })
  return buf.toString('base64')
}

